SELECT ?point ?ts_id WHERE {
  ?zone rdfs:label "Perimeter_bot_ZN_2" .
  ?point brick:isPointOf ?zone ;
         rdf:type ?type .
         # Looking for occupancy sensors or points. Let's search for anything that could be occupancy.
  ?point ref:hasTimeseriesId ?ts_id .
}

SELECT ?point ?ts_id ?type WHERE {
  ?point brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z03> .
  ?point rdf:type ?type .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts_id . }
}
